{
  "probability": 0.99,
  "range_low": 0.92,
  "range_high": 0.98,
  "summary": [
    "606 Mediterranean deaths by February 24, 2026 indicate strong momentum toward high annual mortality.",
    "To hit 900 by end-March, March would need roughly 294 more deaths—a plausible pace given early-2026 data and historical monthly variability.",
    "Historical annual tolls around 2,100–2,500 support the plausibility of reaching 900 relatively early in the year, though revisions and volatility introduce uncertainty.",
    "Factors such as weather, reporting revisions, potential mass-casualty events, and SAR policy can all tilt the trajectory, but the posterior probability remains high."
  ],
  "confidence": "high",
  "narrative": "Early 2026 data show strong momentum toward a high death toll, with 606 fatalities by late February making 900 by end-March plausible. While revisions and volatility could shift the path, the combination of a high anchor and ongoing mortality suggests a high probability, calibrated to about 99% after considering correlated factors.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "reference class is IOM Missing Migrants Mediterranean deaths; anchor probability chosen as a cautious base-rate within a high-mortality context consistent with the supplied forecast anchors."
    },
    "factor_updates": [
      {
        "factor": "pace_of_early_2026_mortality_rate",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by Feb 24, 2026 indicate strong momentum; reaching 900 by end-March would require ~294 more in March, which is plausible given the pace and monthly variability."
      },
      {
        "factor": "weather_and_sea_conditions_march",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "March sea states can sustain high fatality risk; continued crossings could push totals higher."
      },
      {
        "factor": "data_reporting_lags_and_revisions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "IOM counts can be revised upward as reports are confirmed, potentially increasing March totals."
      },
      {
        "factor": "risk_of_single_high_fatality_incident",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "A major shipwreck could disproportionately push the total above 900 regardless of typical pace."
      },
      {
        "factor": "search_and_rescue_policy_effects",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Enhanced SAR or deterrence could reduce deaths, suppressing the probability toward 900."
      }
    ],
    "synthesis_rationale": "Starting from a high anchor, updates reflect momentum and a substantial baseline risk, tempered by potential reductions from policy and rescue efforts and the possibility of data revisions. The 99% posterior is calibrated to account for correlated drivers and the remaining uncertainty."
  }
}

